// Neutral static adaptation of prototype-v24.ts drawVapor/drawBackrooms/drawPerspectiveFloor.
// No artist assets, media URLs, network or global surface targets. Motion is explicit and session-only.
export function attachEnvironment({host,scene,signal,validate,apply,getTargets=()=>[],resolveTarget=()=>null}){
 const doc=host.ownerDocument;let disposed=false,backdrop=null,motion=null;
 host.innerHTML='<h2>Room environment</h2><p>Source-derived procedural backdrop within this room. Optional motion is session-only and starts only when requested. No media compositor or global wallpaper. Expanded presets use room backup format v10 and require native schema13. Cosmic, parallax and custom media wallpaper are not included. Object targets use reviewed IDs and stay within Foundry.</p><label>Surface <select data-environment-target><option value="room">Room backdrop</option><option value="object">Object surface</option></select></label><label>Object target <select data-environment-target-id></select></label><label>Backdrop <select data-environment-preset><option value="off">Off</option><option value="vapor">Vapor</option><option value="backrooms">Backrooms</option><option value="frutiger">Frutiger</option><option value="aurora">Aurora</option><option value="ocean">Ocean</option><option value="raincity">Rain city</option><option value="diner">Diner</option></select></label><label>Opacity <input data-environment-opacity type="number" min="0" max="1" step="0.01" value="0.82"></label><label>Perspective horizon <input data-environment-horizon type="number" min="0.1" max="0.9" step="0.01" value="0.48"></label><button type="button" data-environment-apply>Apply room environment</button><button type="button" data-environment-motion disabled>Start environment motion</button><p data-environment-status role="status"></p>';
 const one=s=>host.querySelector(s),status=one('[data-environment-status]');
 function clear(){motion?.dispose();motion=null;one('[data-environment-motion]').disabled=true;one('[data-environment-motion]').textContent='Start environment motion';backdrop?.remove();backdrop=null;}
 function update(input){if(disposed||signal.aborted)return;const v=validate(input??{preset:'off',opacity:.82,horizon:.48});clear();const targetSelect=one('[data-environment-target-id]');targetSelect.replaceChildren();for(const obj of getTargets()){const option=doc.createElement('option');option.value=obj.id;option.textContent=obj.name;targetSelect.append(option);}if(v.targetId&&!getTargets().some(o=>o.id===v.targetId)){const option=doc.createElement('option');option.value=v.targetId;option.textContent='Unavailable instance: '+v.targetId;targetSelect.append(option);}one('[data-environment-target]').value=v.target||'room';targetSelect.value=v.targetId||getTargets()[0]?.id||'';one('[data-environment-preset]').value=v.preset;one('[data-environment-opacity]').value=String(v.opacity);one('[data-environment-horizon]').value=String(v.horizon);if(v.preset==='off'){status.textContent='Room backdrop off; configuration retained.';return;}
  const surface=v.target==='object'?resolveTarget(v.targetId):scene;if(!surface){status.textContent='Object surface unavailable or hidden; target and configuration retained without fallback.';return;}
  if(['frutiger','aurora','ocean','raincity','diner'].includes(v.preset)){
   const canvas=doc.createElement('canvas');canvas.width=1000;canvas.height=600;canvas.setAttribute('aria-hidden','true');canvas.dataset.environmentBackdrop=v.preset;canvas.style.cssText=`position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:${v.opacity}`;
   try{const context=canvas.getContext('2d');if(!context)throw Error('Canvas unavailable');renderExpandedEnvironment(context,v.preset,1000,600,v.horizon);}catch{status.textContent='Environment canvas unavailable; configuration retained. No rendered result claimed.';return;}
   surface.prepend(canvas);backdrop=canvas;if(v.preset!=='diner'){const win=doc.defaultView;motion=createEnvironmentMotion({draw:t=>renderExpandedEnvironment(canvas.getContext('2d'),v.preset,1000,600,v.horizon,t),request:fn=>win.requestAnimationFrame(fn),cancel:id=>win.cancelAnimationFrame(id),active:()=>!doc.hidden&&canvas.isConnected&&!signal.aborted,onStop:()=>{one('[data-environment-motion]').textContent='Start environment motion';}});one('[data-environment-motion]').disabled=false;}status.textContent='Static '+v.preset+' '+(v.target==='object'?'object surface':'room backdrop')+' rendered at source time zero; no motion or media playback.';return;
  }
  const ns='http://www.w3.org/2000/svg',svg=doc.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 600');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');svg.dataset.environmentBackdrop=v.preset;svg.style.cssText=`position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:${v.opacity}`;
  const add=(tag,attrs)=>{const e=doc.createElementNS(ns,tag);for(const [k,value] of Object.entries(attrs))e.setAttribute(k,String(value));svg.append(e);return e;};
  const colors=v.preset==='vapor'?['#14072e','#5e1d79','#ff6aae']:['#b8ac61','#807744','#393520'];
  svg.style.background=`linear-gradient(to bottom,${colors.join(',')})`; // Original three-stop sky gradient, no document-global ids.
  const line=(x1,y1,x2,y2,stroke)=>add('line',{x1,y1,x2,y2,stroke,'stroke-width':1});
  if(v.preset==='vapor'){const y=204,r=102;add('circle',{cx:500,cy:y,r,fill:'#ffd45c'});for(let i=0;i<6;i++)add('rect',{x:500-r,y:y-r+i*r*.35,width:r*2,height:5,fill:'rgba(255,72,172,.85)'});const horizon=600*v.horizon;for(let i=-12;i<=12;i++)line(500+i*7,horizon,500+i*120,600,'rgba(68,242,255,.5)');for(let y=horizon+10;y<600;y+=Math.max(9,(y-horizon)*.18))line(0,y,1000,y,'rgba(68,242,255,.5)');}
  else{const horizon=252;for(let x=0;x<1000;x+=125){line(x,0,500+(x-500)*.28,horizon,'rgba(55,51,25,.55)');line(500+(x-500)*.28,horizon,x,600,'rgba(55,51,25,.55)');}for(let y=0;y<600;y+=32)line(0,y,1000,y,'rgba(55,51,25,.55)');for(let i=0;i<5;i++)add('rect',{x:1000*(.08+i*.2),y:48,width:110,height:5,fill:'rgba(255,252,195,.78)'});}
  surface.prepend(svg);backdrop=svg;status.textContent='Static '+v.preset+' '+(v.target==='object'?'object surface':'room backdrop')+' rendered; no media playback or motion.';
 }
 const click=()=>{if(disposed||signal.aborted)return;try{const raw=[one('[data-environment-opacity]').value,one('[data-environment-horizon]').value];if(raw.some(v=>!v.trim()))throw Error('Opacity and horizon are required.');const v=validate({preset:one('[data-environment-preset]').value,opacity:Number(raw[0]),horizon:Number(raw[1]),target:one('[data-environment-target]').value,targetId:one('[data-environment-target]').value==='object'?one('[data-environment-target-id]').value:null});apply(v);}catch(e){status.textContent='Environment not applied: '+e.message;}};
 const motionClick=()=>{if(!motion)return;if(motion.running){motion.stop();status.textContent='Environment motion stopped; current frame retained.';}else{motion.start();one('[data-environment-motion]').textContent='Stop environment motion';status.textContent='Explicit session-only procedural motion running; not saved or automatically resumed.';}};const visibility=()=>{if(doc.hidden)motion?.stop();};doc.addEventListener('visibilitychange',visibility);one('[data-environment-motion]').addEventListener('click',motionClick);one('[data-environment-apply]').addEventListener('click',click);const dispose=()=>{if(disposed)return;disposed=true;clear();doc.removeEventListener('visibilitychange',visibility);one('[data-environment-motion]').removeEventListener('click',motionClick);one('[data-environment-apply]').removeEventListener('click',click);signal.removeEventListener('abort',dispose);};signal.addEventListener('abort',dispose,{once:true});return {update,clear,dispose};
}

// Source-owned MIT procedural formulas from prototype-v24.ts, time parameter preserved. No source user data.
export function renderExpandedEnvironment(ctx,preset,w=1000,h=600,horizon=.48,time=0){
 if(!Number.isFinite(time)||time<0||time>86400)throw Error("Invalid bounded environment time");
 if(!ctx||!Number.isFinite(w)||!Number.isFinite(h)||w<2||h<2||w>2048||h>2048||!Number.isFinite(horizon)||horizon<.1||horizon>.9)throw Error("Invalid bounded environment canvas");
 const environmentConfig={horizon:horizon*100,floor:72};
function skyGradient(ctx,w,h,colors){const g=ctx.createLinearGradient(0,0,0,h);colors.forEach((c,i)=>g.addColorStop(i/(colors.length-1),c));ctx.fillStyle=g;ctx.fillRect(0,0,w,h);}
function drawPerspectiveFloor(ctx,w,h,line,fill){const horizon=h*environmentConfig.horizon/100,floor=h*environmentConfig.floor/100;const g=ctx.createLinearGradient(0,horizon,0,h);g.addColorStop(0,'transparent');g.addColorStop(1,fill);ctx.fillStyle=g;ctx.fillRect(0,horizon,w,h-horizon);ctx.strokeStyle=line;ctx.lineWidth=1;for(let i=-12;i<=12;i++){ctx.beginPath();ctx.moveTo(w/2+i*7,horizon);ctx.lineTo(w/2+i*w*.12,h);ctx.stroke();}for(let y=horizon+10;y<h;y+=Math.max(9,(y-horizon)*.18)){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}}
function drawFrutigerWallpaper(ctx,w,h,t){skyGradient(ctx,w,h,['#3cc9ff','#8de7ff','#d8fff0']);const sun=ctx.createRadialGradient(w*.72,h*.22,0,w*.72,h*.22,h*.28);sun.addColorStop(0,'rgba(255,255,215,.95)');sun.addColorStop(.4,'rgba(255,242,122,.35)');sun.addColorStop(1,'transparent');ctx.fillStyle=sun;ctx.fillRect(0,0,w,h);ctx.fillStyle='#31c98c';ctx.beginPath();ctx.moveTo(0,h*.68);ctx.quadraticCurveTo(w*.22,h*.45,w*.45,h*.69);ctx.quadraticCurveTo(w*.7,h*.39,w,h*.65);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='rgba(73,225,255,.74)';ctx.beginPath();ctx.moveTo(0,h*.78);ctx.bezierCurveTo(w*.25,h*(.73+Math.sin(t)*.02),w*.7,h*.88,w,h*.72);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();for(let i=0;i<18;i++){const x=(i*97+t*22)%w,y=h*(.15+(i%6)*.11);ctx.strokeStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.arc(x,y,5+i%4*2,0,Math.PI*2);ctx.stroke();}}
function drawAurora(ctx,w,h,t){skyGradient(ctx,w,h,['#020722','#153258','#07182f']);for(let i=0;i<4;i++){ctx.strokeStyle=['rgba(94,255,203,.36)','rgba(117,181,255,.34)','rgba(255,124,229,.26)','rgba(180,255,121,.24)'][i];ctx.lineWidth=h*.12;ctx.beginPath();for(let x=0;x<=w;x+=12){const y=h*(.2+i*.11)+Math.sin(x*.011+t*.8+i)*h*.09;if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();}drawPerspectiveFloor(ctx,w,h,'rgba(99,220,255,.18)','rgba(15,55,80,.18)');}
function drawOcean(ctx,w,h,t){skyGradient(ctx,w,h,['#051a39','#0a6793','#5ce8d8']);for(let y=0;y<h;y+=18){ctx.strokeStyle=`rgba(190,255,255,${.08+(y/h)*.15})`;ctx.beginPath();for(let x=0;x<=w;x+=12){const yy=y+Math.sin(x*.02+t*1.4+y*.02)*7;if(x===0)ctx.moveTo(x,yy);else ctx.lineTo(x,yy);}ctx.stroke();}for(let i=0;i<20;i++){ctx.strokeStyle='rgba(220,255,255,.45)';ctx.beginPath();ctx.arc((i*83+t*22)%w,h-(i*47+t*18)%h,3+i%4,0,Math.PI*2);ctx.stroke();}}
function drawRainCity(ctx,w,h,t){skyGradient(ctx,w,h,['#06101f','#16324c','#274660']);ctx.fillStyle='#071321';for(let i=0;i<14;i++){const bw=w/14+5,bh=h*(.2+(i%5)*.07);ctx.fillRect(i*w/14,h-bh,bw,bh);ctx.fillStyle=i%3===0?'#56d9ff':'#ff5bc8';for(let y=h-bh+12;y<h-10;y+=14)ctx.fillRect(i*w/14+7,y,3,5);ctx.fillStyle='#071321';}ctx.strokeStyle='rgba(177,230,255,.42)';for(let i=0;i<100;i++){const x=(i*67+t*180)%w,y=(i*97+t*330)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-8,y+18);ctx.stroke();}}
function drawDiner(ctx,w,h,t){skyGradient(ctx,w,h,['#060b1b','#17143a','#541843']);ctx.fillStyle='#ff3e88';ctx.font=`800 ${Math.max(18,h*.12)}px system-ui`;ctx.textAlign='center';ctx.shadowColor='#ff3e88';ctx.shadowBlur=18;ctx.fillText('OPEN 24 HOURS',w/2,h*.3);ctx.shadowBlur=0;ctx.strokeStyle='#58efff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,h*.72);ctx.lineTo(w,h*.72);ctx.stroke();for(let i=0;i<18;i++){ctx.fillStyle=i%2?'#f7f0ef':'#18162b';ctx.fillRect(i*w/18,h*.72,w/18,h*.28);}}
 const draw={frutiger:drawFrutigerWallpaper,aurora:drawAurora,ocean:drawOcean,raincity:drawRainCity,diner:drawDiner}[preset];if(!draw)throw Error("Unsupported expanded environment");ctx.save();try{ctx.clearRect(0,0,w,h);draw(ctx,w,h,time)}finally{ctx.restore()}
}

// Bounded 30fps, explicit opt-in; stop on hidden/detached/abort, never auto-resume.
export function createEnvironmentMotion({draw,request,cancel,active=()=>true,onStop=()=>{}}){
 let running=false,disposed=false,handle=null,start=null,last=null;
 function stop(){const wasRunning=running;running=false;if(handle!==null)cancel(handle);handle=null;start=null;last=null;if(wasRunning)onStop();}
 function frame(now){handle=null;if(!running)return;if(!active()){stop();return;}if(start===null)start=now;if(last===null||now-last>=1000/30){try{draw(Math.min(86400,Math.max(0,(now-start)/1000)));last=now;}catch{stop();return;}}if(running)handle=request(frame);}
 return {get running(){return running;},start(){if(disposed||running||!active())return;running=true;handle=request(frame);},stop,dispose(){stop();disposed=true;}};
}
